import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testRemovesDuplicates() {
        val result = uniquePartners(listOf(4215, 1234, 4215, 5678))
        Assert.assertEquals(3, result.size)
        Assert.assertTrue(result.contains(4215))
        Assert.assertTrue(result.contains(1234))
        Assert.assertTrue(result.contains(5678))
    }

    @Test
    fun testNoDuplicates() {
        val result = uniquePartners(listOf(4215, 1234, 5678))
        Assert.assertEquals(3, result.size)
    }

    @Test
    fun testAllDuplicates() {
        val result = uniquePartners(listOf(4215, 4215, 4215))
        Assert.assertEquals(1, result.size)
        Assert.assertTrue(result.contains(4215))
    }

    @Test
    fun testEmptyList() {
        val result = uniquePartners(listOf())
        Assert.assertTrue(result.isEmpty())
    }
}
